#!/usr/bin/env python3
"""Generate self-contained HCL captions and explicit tofu.* phases."""
import json
from pathlib import Path
root=Path(__file__).resolve().parent
manifest=json.loads((root/'manifest.json').read_text())
for name,metadata in manifest['examples'].items():
    hcl=(root/name/'main.tf').read_text()
    text='# Generated by compare/generate.py. Uses Python 3, curl and AWS CLI for independent verification.\n'
    text+='write_file("comparison-main.tf", '+json.dumps(hcl)+');\n'
    for local,url,key in [('compare-runtime.py','compare/runtime.py','LMAWS_COMPARE_RUNTIME'),('verify_absence.py','scripts/verify_absence.py','LMAWS_COMPARE_VERIFIER')]:
        text+='if (env('+json.dumps(key)+') != null && env('+json.dumps(key)+') != "") { write_file('+json.dumps(local)+', read_file(env('+json.dumps(key)+'))); } else {\n'
        text+='download = system(["curl", "--fail", "--location", "--silent", "--show-error", "--max-time", "45", "https://raw.githubusercontent.com/lmctl-ai/lmaws/main/'+url+'"], 60000);\nassert(download.code == 0);\nwrite_file('+json.dumps(local)+', download.stdout);\n}\n'
    phases={'init':'let ok = tofu.init("infrastructure");','validate':'let ok = tofu.validate("infrastructure");','plan':'let p = tofu.plan("infrastructure"); file_write("plan.json", p.json()); let ok = str_len(tofu.last_error()) == 0;','apply':'let ok = tofu.apply("infrastructure");','inspect':'file_write("snapshot.json", tofu.show_state("infrastructure")); let ok = str_len(tofu.last_error()) == 0;','destroy':'let ok = tofu.destroy("infrastructure");','inspect_after':'file_write("snapshot-after.json", tofu.show_state("infrastructure")); let ok = str_len(tofu.last_error()) == 0;'}
    for phase,code in phases.items():
        text+='phase_'+phase+' = _dsl_ cli="lmcloud" install="github:lmctl-ai/lmcloud@v0.1.9";\n'+code+'\nfile_write("phase-'+phase+'.ok", str(ok));\nfile_write("phase-'+phase+'.error", tofu.last_error());\nend _dsl_\nsavedsl(phase_'+phase+', "phase-'+phase+'.dslb");\n'
    text+='result = system(["python3", "compare-runtime.py", "--name", '+json.dumps(name)+', "--host", dsl_cli(phase_init)[0], "--config", "comparison-main.tf", "--metadata", '+json.dumps(json.dumps(metadata))+'], 900000);\nprintln(result.stdout);\nassert(result.code == 0);\n'
    (root/name/(name+'.lms')).write_text(text)
